def signal(obs):
    # simple momentum: past 10 return predicts next 10
    # use standardized signal
    mid = obs.hist('A','mid', 30)
    if len(mid)<30 or np.isnan(mid).any():
        return {}
    past10 = mid[-1]-mid[-11]  # approx 10 steps back (need account for 10-step call? but hist per step)
    # obs called every 10 steps, so we get update chance each 10 steps
    # naive momentum
    # normalize by volatility
    vol = np.nanstd(np.diff(mid))
    if vol==0 or np.isnan(vol):
        return {}
    sig = past10/vol
    # clip
    sig = max(-1, min(1, sig*0.3))
    return {'A': float(sig)}

def signal(obs):
    mid = obs.hist('A','mid', 110)
    if len(mid) < 105 or np.isnan(mid).any():
        return {}
    # mean reversion for 50 horizon: - past 50
    p50 = mid[-1] - mid[-51]
    p30 = mid[-1] - mid[-31]
    # combine
    # normalize by recent vol
    diffs = np.diff(mid[-60:])
    vol = np.nanstd(diffs) * np.sqrt(50)  # approx scaling
    if vol==0 or np.isnan(vol) or vol==0:
        return {}
    sig = -(0.5*p30 + 0.5*p50) / vol
    # also consider imbalance if available
    # scale to -1..1
    # clip and scale down to reduce turnover cost
    sig = float(np.clip(sig, -1, 1))
    # damp small signals to avoid churn: threshold
    if abs(sig) < 0.1:
        sig = 0
    return {'A': sig}

